import pandas as pd,numpy as np,warnings,pickle
from pymatgen.core import Structure,Element
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
warnings.filterwarnings('ignore')
tr=pd.read_csv('/work/cdft_topo_sp_eg_train.csv');te=pd.read_csv('/work/cdft_topo_pool.csv');df=pd.concat([tr,te],ignore_index=True)

def atom_feats(el):
 e=Element(el);conf=e.full_electronic_structure;row=max(n for n,l,v in conf)
 val={l:sum(v for n,l2,v in conf if l==l2 and n==row-{'s':0,'p':0,'d':1,'f':2}[l]) for l in 'spdf'}
 if e.block=='p':val['d']=0;val['f']=0
 if e.block=='s':val['d']=0;val['f']=0
 if e.block=='d':val['f']=0
 dic={'Z':e.Z,'mass':float(e.atomic_mass),'X':e.X,'row':e.row,'group':e.group,'mendeleev':e.mendeleev_no,'radius':e.atomic_radius,'radcalc':e.atomic_radius_calculated,'ea':e.electron_affinity,'ioniz':e.ionization_energy,'melt':e.melting_point, 'oxmin':min(e.oxidation_states or [0]),'oxmax':max(e.oxidation_states or [0])}
 for b in 'spdf':dic['val'+b]=val[b];dic['unfill'+b]={'s':2,'p':6,'d':10,'f':14}[b]-val[b] if val[b] else 0
 dic['val']=sum(val.values());dic['valnof']=sum(val[b] for b in 'spd')
 for k,v in dic.items():
  try:dic[k]=float(v)
  except:dic[k]=np.nan
 return dic
A={str(el):atom_feats(str(el)) for c in df.formula for el in Structure.from_str(df[df.formula==c].iloc[0].poscar,fmt='poscar').composition.elements}

def feats(r):
 s=Structure.from_str(r.poscar,fmt='poscar');els=s.composition.elements;f=np.array([s.composition.get_atomic_fraction(e) for e in els]);n=len(s);d={}
 a=pd.DataFrame([A[str(e)] for e in els])
 for k in a:
  x=a[k].values;mu=np.sum(f*x)
  d[k+'_mean']=mu;d[k+'_min']=np.min(x);d[k+'_max']=np.max(x);d[k+'_range']=np.ptp(x);d[k+'_dev']=np.sum(f*abs(x-mu))
 for z in range(1,93):d['el_'+Element.from_Z(z).symbol]=s.composition.get_atomic_fraction(Element.from_Z(z))
 for k in ['is_metal','is_transition_metal','is_rare_earth','is_alkali','is_alkaline','is_chalcogen','is_halogen','is_metalloid']:
  d[k]=sum(float(getattr(e,k,False))*w for e,w in zip(els,f))
 for b in 'spdf':d['block_'+b]=sum(w for e,w in zip(els,f) if e.block==b)
 d['n']=n;d['nel']=len(els);d['density']=float(s.density);d['vpa']=s.volume/n
 d['valcell']=d['valnof_mean']*n;d['odd']=round(d['valcell'])%2
 d['pvalcell']=sum(w*n*(A[str(e)]['valnof'] if e.block!='d' else A[str(e)]['valnof']-10) for e,w in zip(els,f))
 d['pvalmod8']=d['pvalcell']%8
 d['entropy']=-sum(f*np.log(f));d['stoich2']=sum(f**2);d['stoich3']=sum(f**3)
 d['soc_mean']=sum(f*np.array([e.Z for e in els])**4)/1e8
 # separate electronegative anion and cation features
 anion=sorted(els,key=lambda e:e.X)[-1];cation=sorted(els,key=lambda e:e.X)[0]
 for tag,e in [('an',anion),('cat',cation)]:
  for k,v in A[str(e)].items():d[tag+'_'+k]=v
  d[tag+'_frac']=s.composition.get_atomic_fraction(e)
 try:
  sg=SpacegroupAnalyzer(s,symprec=.05);d['sg']=sg.get_space_group_number();d['centro']=float(sg.is_laue());ss=sg.get_symmetrized_structure();d['nsites']=len(ss.equivalent_sites)
  for k in ['cubic','tetragonal','hexagonal','trigonal','orthorhombic','monoclinic','triclinic']:d[k]=float(sg.get_crystal_system()==k)
 except:pass
 # near neighbors
 distances=[];cn=[];ion=[];norms=[];homos=[];rn=[]
 for site in s:
  neigh=sorted(s.get_neighbors(site,6),key=lambda a:a.nn_distance)
  if not neigh:continue
  dis=neigh[0].nn_distance; nn=[p for p in neigh if p.nn_distance<dis*1.25]
  distances.append(dis);cn.append(len(nn));x=site.specie.X
  ion.append(np.mean([abs(x-p.specie.X) for p in nn]));homos.append(np.mean([site.specie==p.specie for p in nn]));norms.append(np.mean([p.nn_distance/(float(site.specie.atomic_radius or 1.5)+float(p.specie.atomic_radius or 1.5)) for p in nn]));rn.append(neigh[min(5,len(neigh)-1)].nn_distance/dis)
 for k,vals in [('nn',distances),('cn',cn),('bondX',ion),('bondequal',homos),('bondnorm',norms),('dist_ratio',rn)]:
  for stat,fn in [('mean',np.mean),('min',np.min),('max',np.max),('std',np.std)]:d[k+'_'+stat]=fn(vals)
 return d
X=pd.DataFrame([feats(r) for i,r in df.iterrows()]);X=X.replace([np.inf,-np.inf],np.nan).fillna(X.median()).fillna(0)
pickle.dump((tr,te,X),open('/tmp/features.pkl','wb'))
print(X.shape)

import pickle,numpy as np,pandas as pd
from sklearn.ensemble import RandomForestRegressor,ExtraTreesRegressor,RandomForestClassifier,ExtraTreesClassifier,HistGradientBoostingRegressor
from catboost import CatBoostRegressor,CatBoostClassifier
from sklearn.model_selection import GroupKFold
from sklearn.metrics import mean_absolute_error,mean_squared_error,roc_auc_score,average_precision_score
from sklearn.base import clone
tr,te,X=pickle.load(open('/tmp/features.pkl','rb'));xt=X.iloc[:200];xp=X.iloc[200:];cv=list(GroupKFold(5).split(xt,groups=tr.formula))
regs={
'rf':RandomForestRegressor(n_estimators=500,min_samples_leaf=2,max_features=.8,n_jobs=4,random_state=53),
'et':ExtraTreesRegressor(n_estimators=500,min_samples_leaf=2,max_features=.9,n_jobs=4,random_state=53),
'cat':CatBoostRegressor(iterations=1000,depth=4,learning_rate=.025,l2_leaf_reg=5,verbose=False,thread_count=4,random_seed=53),
}
result=te[['candidate_id','formula']].copy();out=tr[['formula','spillage','band_gap']].copy();scores={};models={}
for label,y in [('gap',tr.band_gap),('sp',tr.spillage),('logsp',np.log(tr.spillage+.02)),('score',tr.spillage*(tr.band_gap>=1)),('pass',(tr.band_gap>=1).astype(int))]:
 for name,reg in regs.items():
  if label=='pass':
   reg={'rf':RandomForestClassifier(n_estimators=500,min_samples_leaf=2,max_features=.8,n_jobs=4,random_state=53),'et':ExtraTreesClassifier(n_estimators=500,min_samples_leaf=2,max_features=.9,n_jobs=4,random_state=53),'cat':CatBoostClassifier(iterations=700,depth=4,learning_rate=.025,l2_leaf_reg=5,verbose=False,thread_count=4,random_seed=53)}[name]
  oof=np.zeros(len(y))
  for a,b in cv:
   m=clone(reg);m.fit(xt.iloc[a],y.iloc[a]);oof[b]=m.predict_proba(xt.iloc[b])[:,1] if label=='pass' else m.predict(xt.iloc[b])
  if label=='pass':print(label,name,'AUC',roc_auc_score(y,oof),'AP',average_precision_score(y,oof))
  else:print(label,name,'MAE',mean_absolute_error(y,oof),'RMSE',np.sqrt(mean_squared_error(y,oof)))
  reg.fit(xt,y);models[label+'_'+name]=reg;pr=reg.predict_proba(xp)[:,1] if label=='pass' else reg.predict(xp)
  if label=='logsp':pr=np.exp(pr)-.02
  result[label+'_'+name]=pr;out[label+'_'+name]=oof
 result[label]=result[[label+'_'+s for s in regs]].mean(axis=1)
result['predscore']=result['pass']*result['sp']
result['logpredscore']=result['pass']*result['logsp']
print(result.sort_values('predscore',ascending=False).round(3).to_string(index=False))
result.to_pickle('/tmp/pred.pkl');out.to_pickle('/tmp/oof.pkl');pickle.dump(models,open('/tmp/models.pkl','wb'))
for lab in ['gap','sp','pass','score']:
 m=models[lab+'_cat']; fi=pd.Series(m.feature_importances_,index=X.columns).sort_values(ascending=False)
 print('\nTop features',lab,fi.head(20).to_string())

